documents.two_drivers:
yamaa: "1.0"
type: spec
domain: XX
input:
  AE: {path: ae.csv, key: [USUBJID], types: {AESEQ: int}}
  DM: {path: dm.csv, key: [USUBJID]}
  CM: {path: cm.csv, types: {CMSEQ: int}}
keys: [USUBJID, SRC, SEQ]
output: {path: out.csv, columns: [USUBJID, SRC, SEQ, X]}
columns:
  - {name: USUBJID, type: str}
  - {name: SRC, type: str}
  - {name: SEQ, type: int}
  - {name: X, type: str, derivation: DM.SEX}
rows:
  - id: ae
    dataset: AE
    derivations: {USUBJID: AE.USUBJID, SRC: "'AE'", SEQ: AE.AESEQ, X: "'OWN'"}
  - id: dm
    dataset: DM
    derivations: {USUBJID: DM.USUBJID, SRC: "'DM'", SEQ: 0}

