documents.ordered:
yamaa: "1.0"
type: spec
domain: XX
input:
  AE: {path: ae.csv, key: [USUBJID], types: {AESEQ: int}}
  DM: {path: dm.csv, key: [USUBJID]}
  CM: {path: cm.csv, types: {CMSEQ: int}}
keys: [USUBJID, SRC, SEQ]
output: {path: out.csv, columns: [USUBJID, SRC, SEQ, X]}
columns:
  - {name: USUBJID, type: str}
  - {name: SRC, type: str}
  - {name: SEQ, type: int}
  - {name: X, type: int, derivation: {case: [{when: "SRC = 'AE'", then: AE.CODE}, {otherwise: DM.CODE}]}}
rows:
  - {id: arm_a, dataset: DM, filter: "DM.ARM = 'A'", derivations: {USUBJID: DM.USUBJID, SRC: "'A'", SEQ: 0}}
  - {id: events, dataset: AE, derivations: {USUBJID: AE.USUBJID, SRC: "'AE'", SEQ: AE.AESEQ}}
  - {id: arm_b, dataset: DM, filter: "DM.ARM = 'B'", derivations: {USUBJID: DM.USUBJID, SRC: "'B'", SEQ: 0}}

documents.serious:
yamaa: "1.0"
type: spec
domain: XX
input:
  AE: {path: ae.csv, key: [USUBJID], types: {AESEQ: int}}
  DM: {path: dm.csv, key: [USUBJID]}
  CM: {path: cm.csv, types: {CMSEQ: int}}
keys: [USUBJID, SRC, SEQ]
output: {path: out.csv, columns: [USUBJID, SRC, SEQ, X]}
intermediates:
  - {id: SER, dataset: AE, filter: "AE.AESER = 'Y'", derivations: {LOWER: {str_case: {source: AE.AETERM, to: lower}}}}
columns:
  - {name: USUBJID, type: str}
  - {name: SRC, type: str}
  - {name: SEQ, type: int}
  - {name: X, type: str, derivation: SER.LOWER}
rows:
  - {id: cm, dataset: CM, derivations: {USUBJID: CM.USUBJID, SRC: "'CM'", SEQ: CM.CMSEQ, X: "'OWN'"}}
  - {id: ser, dataset: SER, derivations: {USUBJID: SER.USUBJID, SRC: "'SER'", SEQ: SER.AESEQ}}
  - {id: dm, dataset: DM, derivations: {USUBJID: DM.USUBJID, SRC: "'DM'", SEQ: 0}}
